package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.WelcomeEmailTemplateVO;

class WelcomeEmailTemplateValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of welcome email template of tenant config")
  void test_welcome_email_template_value_holder_assign_plain_value() {
    Object holder = new Object();
    WelcomeEmailTemplateValueHolder<Object> value = new WelcomeEmailTemplateValueHolder<>(holder);
    Assertions.assertSame(holder, value.welcomeEmailTemplate("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getWelcomeEmailTemplateValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getWelcomeEmailTemplate().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.welcomeEmailTemplateNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getWelcomeEmailTemplateValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getWelcomeEmailTemplate().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of welcome email template of tenant config")
  void test_welcome_email_template_value_holder_assign_value_object() {
    Object holder = new Object();
    WelcomeEmailTemplateValueHolder<Object> value = new WelcomeEmailTemplateValueHolder<>(holder);
    WelcomeEmailTemplateVO vo = WelcomeEmailTemplateVO.from("one");
    Assertions.assertFalse(value.getWelcomeEmailTemplateValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.welcomeEmailTemplate(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getWelcomeEmailTemplateValue().orElseThrow());
    Assertions.assertSame(holder, value.welcomeEmailTemplate(Optional.empty()));
    Assertions.assertFalse(value.getWelcomeEmailTemplateValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.welcomeEmailTemplate(Optional.of(vo)));
    Assertions.assertSame(vo, value.getWelcomeEmailTemplateValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of welcome email template of tenant config against the original")
  void test_welcome_email_template_value_holder_read() {
    Object holder = new Object();
    WelcomeEmailTemplateValueHolder<Object> value = new WelcomeEmailTemplateValueHolder<>(holder);
    WelcomeEmailTemplateVO vo = WelcomeEmailTemplateVO.from("one");
    WelcomeEmailTemplateVO other = WelcomeEmailTemplateVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getWelcomeEmailTemplateValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readWelcomeEmailTemplate(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readWelcomeEmailTemplate(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.welcomeEmailTemplate(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readWelcomeEmailTemplate(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readWelcomeEmailTemplate(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of welcome email template of tenant config")
  void test_welcome_email_template_value_holder_unset() {
    Object holder = new Object();
    WelcomeEmailTemplateValueHolder<Object> value = new WelcomeEmailTemplateValueHolder<>(holder);
    WelcomeEmailTemplateVO vo = WelcomeEmailTemplateVO.from("one");
    value.welcomeEmailTemplate(vo);
    Assertions.assertSame(holder,
        value.unsetWelcomeEmailTemplateIfMatches("welcomeEmailTemplate_other"));
    Assertions.assertTrue(value.getWelcomeEmailTemplateValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetWelcomeEmailTemplateIfMatches("welcomeEmailTemplate"));
    Assertions.assertFalse(value.getWelcomeEmailTemplateValue().isPresent(),
        "The field name must clear the value");
    value.welcomeEmailTemplate(vo);
    Assertions.assertSame(holder, value.unsetWelcomeEmailTemplate());
    Assertions.assertFalse(value.getWelcomeEmailTemplateValue().isPresent(),
        "Unset must clear the value");
  }
}
